import React, { useState, useEffect } from 'react';
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Wine, TrendingUp, Package, Globe, Leaf } from 'lucide-react';
import './App.css';

// AJUSTE ESSA URL CONFORME SEU BACKEND
const API_BASE = 'http://localhost:8000/api';

export default function WineDashboard() {
  const [activeTab, setActiveTab] = useState('producao');
  const [ano, setAno] = useState(2024);
  const [data, setData] = useState([]);
  const [comparativo, setComparativo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Estados dos filtros específicos de cada aba
  const [filters, setFilters] = useState({
    producao: { categoria: '', produto: '' },
    comercio: { categoria: '', produto: '' },
    exportacao: { tipo: '', pais: '' },
    importacao: { tipo: '', pais: '' },
    processamento: { tipo: '', cultivar: '' }
  });

  // Opções disponíveis para cada filtro
  const [options, setOptions] = useState({
    categorias: [],
    produtos: [],
    tipos: [],
    paises: [],
    cultivares: []
  });

  const colors = {
    primary: '#8B5CF6',
    secondary: '#F3F4F6',
    accent: '#7C3AED',
    text: '#1F2937',
    border: '#E5E7EB'
  };

  const tabs = [
    { id: 'producao', label: 'Produção', icon: Wine },
    { id: 'exportacao', label: 'Exportação', icon: Globe },
    { id: 'importacao', label: 'Importação', icon: Package },
    { id: 'comercio', label: 'Comércio', icon: TrendingUp },
    { id: 'processamento', label: 'Processamento', icon: Leaf }
  ];

  useEffect(() => {
    fetchData();
    fetchFilterOptions();
  }, [activeTab, ano, filters]);

  const fetchFilterOptions = async () => {
    try {
      // Busca SEM filtro de ano pra pegar TODOS os dados disponíveis
      const endpoints = {
        producao: `${API_BASE}/Producao/`,
        comercio: `${API_BASE}/Comercio/`,
        exportacao: `${API_BASE}/Exportacao/`,
        importacao: `${API_BASE}/Importacao/`,
        processamento: `${API_BASE}/Processamento/`
      };

      const response = await fetch(endpoints[activeTab]);
      if (!response.ok) return;

      const result = await response.json();
      const allData = Array.isArray(result) ? result : result.results || [];

      console.log(`Dados de ${activeTab}:`, allData.length);

      // Extrai valores únicos pra cada filtro
      if (activeTab === 'producao' || activeTab === 'comercio') {
        const categorias = [...new Set(allData.map(item => item.Categoria).filter(Boolean))].sort();
        const produtos = [...new Set(allData.map(item => item.Produto).filter(Boolean))].sort();
        setOptions({ categorias, produtos, tipos: [], paises: [], cultivares: [] });
      } else if (activeTab === 'exportacao' || activeTab === 'importacao') {
        const tipos = [...new Set(allData.map(item => item.Tipo).filter(Boolean))].sort();
        const paises = [...new Set(allData.map(item => item.Países).filter(Boolean))].sort();
        setOptions({ categorias: [], produtos: [], tipos, paises, cultivares: [] });
      } else if (activeTab === 'processamento') {
        const tipos = [...new Set(allData.map(item => item.Tipo).filter(Boolean))].sort();
        const cultivares = [...new Set(allData.map(item => item.Cultivar).filter(Boolean))].sort();
        setOptions({ categorias: [], produtos: [], tipos, paises: [], cultivares });
      }
    } catch (error) {
      console.error('Erro ao buscar opções de filtro:', error);
    }
  };

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const currentFilters = filters[activeTab];
      let url = '';

      const endpoints = {
        producao: `${API_BASE}/Producao/?ano=${ano}`,
        exportacao: `${API_BASE}/Exportacao/?ano=${ano}`,
        importacao: `${API_BASE}/Importacao/?ano=${ano}`,
        comercio: `${API_BASE}/Comercio/?ano=${ano}`,
        processamento: `${API_BASE}/Processamento/?ano=${ano}`
      };

      url = endpoints[activeTab];

      // Adiciona filtros específicos
      if (activeTab === 'producao' || activeTab === 'comercio') {
        if (currentFilters.categoria) url += `&categoria=${currentFilters.categoria}`;
        if (currentFilters.produto) url += `&produto=${currentFilters.produto}`;
      } else if (activeTab === 'exportacao' || activeTab === 'importacao') {
        if (currentFilters.tipo) url += `&tipo=${currentFilters.tipo}`;
        if (currentFilters.pais) url += `&pais=${currentFilters.pais}`;
      } else if (activeTab === 'processamento') {
        if (currentFilters.tipo) url += `&tipo=${currentFilters.tipo}`;
        if (currentFilters.cultivar) url += `&cultivar=${currentFilters.cultivar}`;
      }

      const response = await fetch(url);
      if (!response.ok) throw new Error(`Erro ${response.status}`);

      const result = await response.json();
      setData(Array.isArray(result) ? result : result.results || []);

      // Fetch comparativo
      const compResponse = await fetch(`${API_BASE}/comparativo/${ano}/`);
      if (compResponse.ok) {
        const compData = await compResponse.json();
        setComparativo(compData);
      }
    } catch (error) {
      console.error('Erro ao buscar dados:', error);
      setError(`Erro ao carregar dados: ${error.message}`);
      setData([]);
    }
    setLoading(false);
  };

  const handleFilterChange = (filterKey, value) => {
    setFilters(prev => ({
      ...prev,
      [activeTab]: {
        ...prev[activeTab],
        [filterKey]: value
      }
    }));
  };

  const getChartData = () => {
    if (!data || data.length === 0) return [];

    if (activeTab === 'producao' || activeTab === 'comercio') {
      // Agrupa por Produto (que é mais granular que Categoria)
      const grouped = {};
      data.forEach(item => {
        const key = item.Produto || item.Categoria || 'N/A';
        grouped[key] = (grouped[key] || 0) + (item.Quantidade_L || 0);
      });
      return Object.entries(grouped)
        .map(([produto, quantidade]) => ({ categoria: produto, quantidade }))
        .sort((a, b) => b.quantidade - a.quantidade)
        .slice(0, 10);
    }

    if (activeTab === 'exportacao' || activeTab === 'importacao') {
      const grouped = {};
      data.forEach(item => {
        const key = item.Países || 'N/A';
        grouped[key] = (grouped[key] || 0) + (item.Quantidade_Kg || 0);
      });
      return Object.entries(grouped)
        .map(([pais, quantidade]) => ({ pais, quantidade }))
        .sort((a, b) => b.quantidade - a.quantidade)
        .slice(0, 10);
    }

    if (activeTab === 'processamento') {
      const grouped = {};
      data.forEach(item => {
        const key = item.Cultivar || 'N/A';
        grouped[key] = (grouped[key] || 0) + (item.Quantidade_Kg || 0);
      });
      return Object.entries(grouped)
        .map(([cultivar, quantidade]) => ({ cultivar, quantidade }))
        .sort((a, b) => b.quantidade - a.quantidade)
        .slice(0, 10);
    }

    return [];
  };

  const renderFilters = () => {
    const filterStyle = {
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    };

    const selectStyle = {
      padding: '8px 12px',
      borderRadius: '6px',
      border: `2px solid ${colors.primary}`,
      fontSize: '14px',
      cursor: 'pointer',
      color: colors.text
    };

    const labelStyle = {
      fontWeight: '600',
      color: colors.text,
      fontSize: '14px'
    };

    if (activeTab === 'producao' || activeTab === 'comercio') {
      return (
        <>
          <label style={filterStyle}>
            <span style={labelStyle}>Categoria:</span>
            <select
              value={filters[activeTab].categoria}
              onChange={(e) => handleFilterChange('categoria', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todas</option>
              {options.categorias.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </label>
          <label style={filterStyle}>
            <span style={labelStyle}>Produto:</span>
            <select
              value={filters[activeTab].produto}
              onChange={(e) => handleFilterChange('produto', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todos</option>
              {options.produtos.map(prod => (
                <option key={prod} value={prod}>{prod}</option>
              ))}
            </select>
          </label>
        </>
      );
    }

    if (activeTab === 'exportacao' || activeTab === 'importacao') {
      return (
        <>
          <label style={filterStyle}>
            <span style={labelStyle}>País:</span>
            <select
              value={filters[activeTab].pais}
              onChange={(e) => handleFilterChange('pais', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todos</option>
              {options.paises.map(pais => (
                <option key={pais} value={pais}>{pais}</option>
              ))}
            </select>
          </label>
          <label style={filterStyle}>
            <span style={labelStyle}>Tipo:</span>
            <select
              value={filters[activeTab].tipo}
              onChange={(e) => handleFilterChange('tipo', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todos</option>
              {options.tipos.map(tipo => (
                <option key={tipo} value={tipo}>{tipo}</option>
              ))}
            </select>
          </label>
        </>
      );
    }

    if (activeTab === 'processamento') {
      return (
        <>
          <label style={filterStyle}>
            <span style={labelStyle}>Cultivar:</span>
            <select
              value={filters[activeTab].cultivar}
              onChange={(e) => handleFilterChange('cultivar', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todos</option>
              {options.cultivares.map(cult => (
                <option key={cult} value={cult}>{cult}</option>
              ))}
            </select>
          </label>
          <label style={filterStyle}>
            <span style={labelStyle}>Tipo:</span>
            <select
              value={filters[activeTab].tipo}
              onChange={(e) => handleFilterChange('tipo', e.target.value)}
              style={selectStyle}
            >
              <option value="">Todos</option>
              {options.tipos.map(tipo => (
                <option key={tipo} value={tipo}>{tipo}</option>
              ))}
            </select>
          </label>
        </>
      );
    }

    return null;
  };

  return (
    <div style={{ backgroundColor: '#FAFBFC', minHeight: '100vh', padding: '20px' }}>
      {/* Header */}
      <div style={{
        background: `linear-gradient(135deg, ${colors.primary} 0%, ${colors.accent} 100%)`,
        color: 'white',
        padding: '40px 20px',
        borderRadius: '12px',
        marginBottom: '30px',
        boxShadow: '0 10px 30px rgba(139, 92, 246, 0.2)'
      }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '10px' }}>
            <Wine size={40} />
            <h1 style={{ margin: 0, fontSize: '32px', fontWeight: 'bold' }}>Wine Analytics</h1>
          </div>
          <p style={{ margin: 0, opacity: 0.9 }}>Dashboard de Produção e Comercialização de Vinhos</p>
        </div>
      </div>

      {/* Controls */}
      <div style={{ maxWidth: '1200px', margin: '0 auto 30px' }}>
        {error && (
          <div style={{
            backgroundColor: '#FEE2E2',
            color: '#DC2626',
            padding: '12px 16px',
            borderRadius: '8px',
            marginBottom: '20px',
            border: '1px solid #FECACA'
          }}>
            ⚠️ {error}
          </div>
        )}

        <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span style={{ fontWeight: '600', color: colors.text }}>Ano:</span>
            <select
              value={ano}
              onChange={(e) => setAno(parseInt(e.target.value))}
              style={{
                padding: '8px 12px',
                borderRadius: '6px',
                border: `2px solid ${colors.primary}`,
                fontSize: '14px',
                cursor: 'pointer',
                color: colors.text
              }}
            >
              {[2024, 2023, 2022, 2021, 2020, 2019, 2018, 2017, 2016, 2015].map(y => (
                <option key={y} value={y}>{y}</option>
              ))}
            </select>
          </label>
        </div>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: '10px', overflowX: 'auto', paddingBottom: '10px' }}>
          {tabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                style={{
                  padding: '12px 20px',
                  borderRadius: '8px',
                  border: 'none',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  fontWeight: '600',
                  fontSize: '14px',
                  transition: 'all 0.3s ease',
                  backgroundColor: activeTab === tab.id ? colors.primary : colors.secondary,
                  color: activeTab === tab.id ? 'white' : colors.text,
                  boxShadow: activeTab === tab.id ? `0 4px 12px rgba(139, 92, 246, 0.3)` : 'none'
                }}
              >
                <Icon size={18} />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Filtros Dinâmicos */}
        <div style={{ display: 'flex', gap: '10px', marginTop: '15px', flexWrap: 'wrap' }}>
          {renderFilters()}
        </div>
      </div>

      {/* Main Content */}
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        {/* Comparativo Card */}
        {comparativo && (
          <div style={{
            backgroundColor: 'white',
            padding: '20px',
            borderRadius: '12px',
            marginBottom: '30px',
            border: `1px solid ${colors.border}`,
            boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
          }}>
            <h3 style={{ color: colors.primary, marginTop: 0, marginBottom: '15px' }}>
              📊 Comparativo {ano}
            </h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px' }}>
              <div style={{ padding: '15px', backgroundColor: colors.secondary, borderRadius: '8px', borderLeft: `4px solid ${colors.primary}` }}>
                <p style={{ margin: '0 0 8px', color: colors.text, fontSize: '14px', opacity: 0.7 }}>Produção Total</p>
                <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: colors.primary }}>
                  {comparativo.producao_total_L?.toLocaleString() || 'N/A'} L
                </p>
              </div>
              <div style={{ padding: '15px', backgroundColor: colors.secondary, borderRadius: '8px', borderLeft: `4px solid ${colors.accent}` }}>
                <p style={{ margin: '0 0 8px', color: colors.text, fontSize: '14px', opacity: 0.7 }}>Exportação Total</p>
                <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: colors.accent }}>
                  {comparativo.exportacao_total_Kg?.toLocaleString() || 'N/A'} kg
                </p>
              </div>
              <div style={{ padding: '15px', backgroundColor: colors.secondary, borderRadius: '8px', borderLeft: `4px solid #10B981` }}>
                <p style={{ margin: '0 0 8px', color: colors.text, fontSize: '14px', opacity: 0.7 }}>% Exportado</p>
                <p style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#10B981' }}>
                  {comparativo.percentual_exportado || 0}%
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Charts */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: colors.primary }}>
            <p style={{ fontSize: '18px', fontWeight: '600' }}>Carregando dados...</p>
          </div>
        ) : data.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px', color: colors.text }}>
            <p style={{ fontSize: '16px' }}>Nenhum dado disponível para os filtros selecionados</p>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '20px' }}>
            {/* Bar Chart */}
            <div style={{
              backgroundColor: 'white',
              padding: '20px',
              borderRadius: '12px',
              border: `1px solid ${colors.border}`,
              boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
            }}>
              <h3 style={{ color: colors.primary, marginTop: 0, marginBottom: '15px' }}>
                {activeTab === 'producao' || activeTab === 'comercio' ? 'Por Categoria' : activeTab === 'processamento' ? 'Por Cultivar' : 'Por País'}
              </h3>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={getChartData()}>
                  <CartesianGrid strokeDasharray="3 3" stroke={colors.border} />
                  <XAxis 
                    dataKey={activeTab === 'processamento' ? 'cultivar' : (activeTab === 'exportacao' || activeTab === 'importacao' ? 'pais' : 'categoria')} 
                    angle={-45} 
                    textAnchor="end" 
                    height={80} 
                    fontSize={12} 
                  />
                  <YAxis stroke={colors.text} />
                  <Tooltip contentStyle={{ borderRadius: '8px', border: `1px solid ${colors.primary}` }} />
                  <Bar dataKey="quantidade" fill={colors.primary} radius={[8, 8, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>

            {/* Pie Chart */}
            <div style={{
              backgroundColor: 'white',
              padding: '20px',
              borderRadius: '12px',
              border: `1px solid ${colors.border}`,
              boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
            }}>
              <h3 style={{ color: colors.primary, marginTop: 0, marginBottom: '15px' }}>
                Distribuição
              </h3>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={getChartData().slice(0, 5)}
                    dataKey="quantidade"
                    nameKey={activeTab === 'processamento' ? 'cultivar' : (activeTab === 'exportacao' || activeTab === 'importacao' ? 'pais' : 'categoria')}
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    label
                  >
                    {[colors.primary, colors.accent, '#10B981', '#F59E0B', '#EF4444'].map((color, i) => (
                      <Cell key={`cell-${i}`} fill={color} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {/* Data Table */}
        {data.length > 0 && (
          <div style={{
            backgroundColor: 'white',
            padding: '20px',
            borderRadius: '12px',
            marginTop: '20px',
            border: `1px solid ${colors.border}`,
            boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
            overflowX: 'auto'
          }}>
            <h3 style={{ color: colors.primary, marginTop: 0, marginBottom: '15px' }}>
              Dados Detalhados
            </h3>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ borderBottom: `2px solid ${colors.primary}` }}>
                  {(activeTab === 'producao' || activeTab === 'comercio') && (
                    <>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Categoria</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Produto</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Quantidade (L)</th>
                    </>
                  )}
                  {(activeTab === 'exportacao' || activeTab === 'importacao') && (
                    <>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>País</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Tipo</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Quantidade (kg)</th>
                    </>
                  )}
                  {activeTab === 'processamento' && (
                    <>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Cultivar</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Tipo</th>
                      <th style={{ padding: '12px', textAlign: 'left', color: colors.primary, fontWeight: 'bold' }}>Quantidade (kg)</th>
                    </>
                  )}
                </tr>
              </thead>
              <tbody>
                {data.slice(0, 10).map((item, idx) => (
                  <tr key={idx} style={{ borderBottom: `1px solid ${colors.border}` }}>
                    {(activeTab === 'producao' || activeTab === 'comercio') && (
                      <>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Categoria}</td>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Produto}</td>
                        <td style={{ padding: '12px', color: colors.text, fontWeight: '600' }}>{item.Quantidade_L?.toLocaleString()}</td>
                      </>
                    )}
                    {(activeTab === 'exportacao' || activeTab === 'importacao') && (
                      <>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Países}</td>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Tipo}</td>
                        <td style={{ padding: '12px', color: colors.text, fontWeight: '600' }}>{item.Quantidade_Kg?.toLocaleString()}</td>
                      </>
                    )}
                    {activeTab === 'processamento' && (
                      <>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Cultivar}</td>
                        <td style={{ padding: '12px', color: colors.text }}>{item.Tipo}</td>
                        <td style={{ padding: '12px', color: colors.text, fontWeight: '600' }}>{item.Quantidade_Kg?.toLocaleString()}</td>
                      </>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
